import openpyxl, re
wb=openpyxl.load_workbook('extraction/penford.xlsx')
ws=wb['Deal ledger']; rd=wb['Rounds']; qs=wb['Questions']; df=wb['Deal facts']
print('sheets',wb.sheetnames)
# 1. Round types
bad=[(r,ws.cell(r,7).value) for r in range(2,ws.max_row+1)
     if not (isinstance(ws.cell(r,7).value,int) or ws.cell(r,7).value=='post')]
print('bad rounds:',bad)
# 2. Round opened rows carry positive round
for r in range(2,ws.max_row+1):
    if ws.cell(r,5).value=='Round opened':
        print('Round opened row',r,'round',repr(ws.cell(r,7).value))
# 3. Rounds sheet vs ledger
led={(ws.cell(r,6).value,ws.cell(r,7).value) for r in range(2,ws.max_row+1)}
for r in range(2,rd.max_row+1):
    k=(rd.cell(r,1).value,rd.cell(r,2).value)
    print('Rounds',k,'in ledger:',k in led)
# 4. Questions rows-affected vs flags
def expand(s):
    out=[]
    for part in str(s).split(','):
        part=part.strip()
        if '-' in part:
            a,b=part.split('-'); out+=list(range(int(a),int(b)+1))
        elif part: out.append(int(part))
    return out
flags={ws.cell(r,1).value: re.findall(r'Q\d+', ws.cell(r,18).value or '') for r in range(2,ws.max_row+1)}
for r in range(2,qs.max_row+1):
    q=qs.cell(r,1).value
    miss=[n for n in expand(qs.cell(r,5).value) if q not in flags.get(n,[])]
    print(q,'missing flags:',miss)
# reverse: flagged rows not cited
cited={}
for r in range(2,qs.max_row+1):
    cited[qs.cell(r,1).value]=set(expand(qs.cell(r,5).value))
for n,fl in flags.items():
    for q in fl:
        if n not in cited.get(q,set()): print('row',n,'flags',q,'but not cited')
# 5. Deal facts
for r in range(2,df.max_row+1):
    if df.cell(r,1).value=='Number of processes':
        print('Number of processes:',repr(df.cell(r,2).value),'ledger processes:',sorted({ws.cell(x,6).value for x in range(2,ws.max_row+1)}))
print('freeze',[(w.title,w.freeze_panes,w.auto_filter.ref) for w in wb])
print('date fmt T2',ws['T2'].number_format,'G2 fmt',ws['G2'].number_format)
