import openpyxl
def dump(p):
    wb=openpyxl.load_workbook(p); d={}
    for ws in wb:
        for r in range(1,ws.max_row+1):
            for c in range(1,ws.max_column+1):
                v=ws.cell(r,c).value
                if v is not None: d[(ws.title,r,c)]=v
    return d
a=dump('/tmp/penford_backup.xlsx'); b=dump('extraction/penford.xlsx')
keys=sorted(set(a)|set(b))
for k in keys:
    if a.get(k)!=b.get(k):
        if k[0]=='Deal ledger' and k[2]==7: continue
        print(k, '|OLD|', repr(a.get(k))[:90], '|NEW|', repr(b.get(k))[:90])
